sp_widget.client_script:
function($scope) {

    var c = this;


    // =====================================================
    // SEARCH
    // =====================================================

    c.searchQuery = "";


    // =====================================================
    // ADVISOR FILTER
    // =====================================================

    c.filterAdvisors = function(advisor) {

        if (!c.searchQuery) {

            return true;

        }


        var search =
            String(
                c.searchQuery
            ).toLowerCase();


        var name =
            String(
                advisor.name || ""
            ).toLowerCase();


        var email =
            String(
                advisor.email || ""
            ).toLowerCase();


        var department =
            String(
                advisor.department || ""
            ).toLowerCase();


        var role =
            String(
                advisor.role || ""
            ).toLowerCase();


        return (
            name.indexOf(search) !== -1 ||
            email.indexOf(search) !== -1 ||
            department.indexOf(search) !== -1 ||
            role.indexOf(search) !== -1
        );

    };


    // =====================================================
    // CAPACITY COLOR
    // =====================================================

    c.getCapacityColor =
        function(percent) {

            percent =
                parseInt(
                    percent,
                    10
                ) || 0;


            if (percent >= 100) {

                return "#ea5455";

            }


            if (percent >= 85) {

                return "#ff9f43";

            }


            if (percent >= 60) {

                return "#0066ff";

            }


            return "#00b074";

        };


    // =====================================================
    // DEFAULT DATA
    // =====================================================

    c.data =
        c.data || {};


    c.data.advisors =
        c.data.advisors || [];

}

