function() {

var c = this;

c.question = '';

c.loading = false;


if (!c.data.messages) {

    c.data.messages = [];

}


// =====================================================
// SEND QUESTION
// =====================================================

c.sendQuestion = function() {

    if (c.loading) {
        return;
    }


    var question =
        (c.question || '').trim();


    if (!question) {
        return;
    }


    // -----------------------------------------------
    // USER MESSAGE
    // -----------------------------------------------

    c.data.messages.push({

        type: 'user',

        text: question

    });


    // -----------------------------------------------
    // SEARCH MESSAGE
    // -----------------------------------------------

    c.data.messages.push({

        type: 'searching',

        text:
            'Let me look up information related to ' +
            question +
            ' for you.'

    });


    c.loading = true;

    var submittedQuestion =
        question;

    c.question = '';


    // -----------------------------------------------
    // SERVER CALL
    // -----------------------------------------------

    c.server.get({

        action: 'ask',

        question:
            submittedQuestion

    }).then(function(response) {


        // -------------------------------------------
        // REMOVE SEARCH MESSAGE
        // -------------------------------------------

        for (
            var i = c.data.messages.length - 1;
            i >= 0;
            i--
        ) {

            if (
                c.data.messages[i].type ==
                'searching'
            ) {

                c.data.messages.splice(
                    i,
                    1
                );

                break;

            }

        }


        // -------------------------------------------
        // RESPONSE
        // -------------------------------------------

        if (
            response.data &&
            response.data.success
        ) {

            c.data.messages.push({

                type: 'answer',

                title:
                    response.data.title,

                introduction:
                    response.data.introduction,

                sections:
                    response.data.sections || [],

                summary:
                    response.data.summary,

                articles:
                    response.data.articles || [],

                showSteps: false,

                showSources: false

            });

        } else {

            c.data.messages.push({

                type: 'error',

                text:
                    response.data.error ||
                    'No relevant information was found in the VisaGuardian Knowledge Base.'

            });

        }


        c.loading = false;


        // -------------------------------------------
        // SCROLL
        // -------------------------------------------

        setTimeout(function() {

            var chat =
                document.getElementById(
                    'vg-chat'
                );


            if (chat) {

                chat.scrollTop =
                    chat.scrollHeight;

            }

        }, 100);

    });

};


// =====================================================
// SUGGESTION
// =====================================================

c.askSuggestion = function(question) {

    c.question =
        question;

    c.sendQuestion();

};


// =====================================================
// ENTER
// =====================================================

c.handleKeyPress = function(event) {

    if (
        event.which === 13 ||
        event.keyCode === 13
    ) {

        event.preventDefault();

        c.sendQuestion();

    }

};


// =====================================================
// COPY ANSWER
// =====================================================

c.copyAnswer = function(message) {

    var text =
        message.title +
        '\n\n' +
        (message.introduction || '') +
        '\n\n';


    if (message.sections) {

        message.sections.forEach(
            function(section) {

                text +=
                    section.title +
                    '\n';


                if (section.text) {

                    text +=
                        section.text +
                        '\n';

                }


                if (
                    section.bullets
                ) {

                    section.bullets.forEach(
                        function(item) {

                            text +=
                                '• ' +
                                item +
                                '\n';

                        }
                    );

                }


                if (
                    section.steps
                ) {

                    section.steps.forEach(
                        function(item, index) {

                            text +=
                                (index + 1) +
                                '. ' +
                                item +
                                '\n';

                        }
                    );

                }


                text += '\n';

            }
        );

    }


    text +=
        'Summary:\n' +
        (message.summary || '');


    if (
        navigator.clipboard
    ) {

        navigator.clipboard.writeText(
            text
        );

    }

};


// =====================================================
// FEEDBACK
// =====================================================

c.feedback = function(
    message,
    type
) {

    console.log(
        'VisaGuardian AI feedback:',
        type
    );

};
