    flex: 1;

    overflow-y: auto;

    overflow-x: hidden;

    padding-top: 5px;

    scrollbar-width: thin;

    scrollbar-color: rgba(255,255,255,0.25) transparent;
}


/* Chrome scrollbar */

.vg-sidebar-nav::-webkit-scrollbar {

    width: 5px;
}


.vg-sidebar-nav::-webkit-scrollbar-track {

    background: transparent;
}


.vg-sidebar-nav::-webkit-scrollbar-thumb {

    background: rgba(255,255,255,0.25);

    border-radius: 10px;
}


/* =====================================================
   NAV ITEM
   ===================================================== */

.vg-nav-item {

    height: 54px;

    min-height: 54px;

    display: flex;

    align-items: center;

    padding: 0 20px;

    color: #ffffff !important;

    text-decoration: none !important;

    font-size: 14px;

    box-sizing: border-box;

    transition: all 0.2s ease;
}


.vg-nav-item:hover {

    background: #1d4d91;

    color: #ffffff !important;

    text-decoration: none !important;
}


.vg-nav-item.active {

    background: #2864e8;

    font-weight: 600;
}


/* =====================================================
   ICON
   ===================================================== */

.vg-nav-icon {

    width: 35px;

    min-width: 35px;

    font-size: 19px;

    text-align: left;

    color: #dceaff;
}


/* =====================================================
   NOTIFICATION
   ===================================================== */

.vg-notification-badge {

    margin-left: auto;

    width: 22px;

    height: 22px;

    border-radius: 50%;

    background: #ff3d45;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 11px;

    font-weight: 700;
}


/* =====================================================
   USER SECTION
   ===================================================== */

.vg-sidebar-user {

    height: 88px;

    min-height: 88px;

    background: #0a2550;

    border-top: 1px solid rgba(255,255,255,0.12);

    display: flex;

    align-items: center;

    padding: 10px 14px;

    box-sizing: border-box;
}


.vg-user-avatar {

    width: 48px;

    height: 48px;

    min-width: 48px;

    border-radius: 50%;

    background: #dce8ff;

    border: 2px solid #3680ff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;

    margin-right: 10px;
}


.vg-user-info {

    overflow: hidden;
}


.vg-user-name {

    font-size: 15px;

    font-weight: 700;

    white-space: nowrap;
}


.vg-user-type {

    font-size: 12px;

    color: #c1d0e5;

    margin-top: 3px;
}


.vg-user-id {

    font-size: 11px;

    color: #9fb4d0;

    margin-top: 2px;
}


/* =====================================================
   MAIN CONTENT
   IMPORTANT
   ===================================================== */

.vg-main-content {

    margin-left: 270px;

    min-height: 100vh;

    width: calc(100% - 270px);

    box-sizing: border-box;
}


/* =====================================================
   RESPONSIVE
   ===================================================== */

@media (max-width: 768px) {

    .vg-sidebar {

        width: 230px;

    }

    .vg-main-content {

        margin-left: 230px;

        width: calc(100% - 230px);

    }

}

