api.controller = function($scope) {

var c = this;

c.ai_question = "";


// =====================================================
// PAGE NAVIGATION
// =====================================================

c.openPage = function(pageId) {

    if (!pageId) {
        return;
    }

    window.location.href = "?id=" + pageId;

};


// =====================================================
// OPEN CASE
// =====================================================

c.openCase = function(sysId) {

    if (!sysId) {
        return;
    }

    window.location.href =
        "?id=case_details&sys_id=" +
        sysId;

};


// =====================================================
// AI ASSISTANT
// =====================================================

c.askAI = function(question) {

    if (!question) {
        return;
    }

    question =
        String(question).trim();

    if (!question) {
        return;
    }


    /*
     * Save the question so the AI page can receive it.
     */

    sessionStorage.setItem(
        "vg_ai_question",
        question
    );


    /*
     * Open your AI chat page.
     */

    window.location.href =
        "student?id=vg_ai_chat";

};


// =====================================================
// ENTER KEY FOR AI
// =====================================================

c.checkAIEnter = function(event) {

    if (event.which === 13) {

        c.askAI(
            c.ai_question
        );

    }

};
};



