api.controller = function() {

var c = this;

// =========================================================
// 1. Load profile data received from Server Script
// =========================================================

c.profile = c.data.profile || {};
c.advisor_context = c.data.advisor_context || {};


// =========================================================
// 2. Check whether profile loaded successfully
// =========================================================

c.profileLoaded = function() {

    return c.profile.found === true;

};


// =========================================================
// 3. Get Advisor full name
// =========================================================

c.getFullName = function() {

    return c.profile.name || 'Advisor';

};


// =========================================================
// 4. Get User ID
// =========================================================

c.getUserName = function() {

    return c.profile.user_name || 'Not available';

};


// =========================================================
// 5. Get Email
// =========================================================

c.getEmail = function() {

    return c.profile.email || 'Not available';

};


// =========================================================
// 6. Get Job Title
// =========================================================

c.getJobTitle = function() {

    return c.profile.title || 'Advisor';

};


// =========================================================
// 7. Get Department
// =========================================================

c.getDepartment = function() {

    return c.profile.department || 'Not available';

};


// =========================================================
// 8. Get Phone
// =========================================================

c.getPhone = function() {

    return c.profile.phone || 'Not available';

};


// =========================================================
// 9. Get Mobile Phone
// =========================================================

c.getMobilePhone = function() {

    return c.profile.mobile_phone || 'Not available';

};


// =========================================================
// 10. Get Location
// =========================================================

c.getLocation = function() {

    return c.profile.location || 'Not available';

};


// =========================================================
// 11. Generate Advisor initials
// =========================================================

c.getInitials = function() {

    var name = c.profile.name;

    if (!name) {
        return 'AD';
    }

    var parts = name.trim().split(/\s+/);

    if (parts.length === 1) {
        return parts[0].substring(0, 2).toUpperCase();
    }

    return (
        parts[0].charAt(0) +
        parts[parts.length - 1].charAt(0)
    ).toUpperCase();

};


// =========================================================
// 12. Check Advisor role
// =========================================================

c.isAdvisor = function() {

    return c.advisor_context.is_advisor === true;

};


// =========================================================
// 13. Get logged-in user's display name
// =========================================================

c.getLoggedInUser = function() {

    return c.advisor_context.logged_in_user ||
           c.profile.name ||
           'Advisor';

};


// =========================================================
// 14. Get user Sys ID
// =========================================================

c.getUserSysId = function() {

    return c.advisor_context.user_sys_id ||
           c.profile.sys_id ||
           '';

};


// =========================================================
// 15. Error handling
// =========================================================

c.hasError = function() {

    return c.profile.error === true;

};


c.getErrorMessage = function() {

    return c.profile.message ||
           'Unable to load profile information.';

};
}; and server script

(function() {

// ==========================================
// DEFAULT DATA
// ==========================================

data.advisor_found = false;
data.error = "";

data.advisor = {
    sys_id: "",
    user_name: "",
    full_name: "",
    first_name: "",
    last_name: "",
    email: "",
    title: "",
    department: "",
    mobile_phone: "",
    location: "",
    last_login: ""
};


// ==========================================
// CHECK LOGIN
// ==========================================

if (!gs.isLoggedIn() || gs.getUserName() == "guest") {

    data.error =
        "You must be logged in to view your advisor profile.";

    return;
}


// ==========================================
// GET CURRENT LOGGED-IN USER
// ==========================================

var currentUserId =
    gs.getUserID();


if (!currentUserId) {

    data.error =
        "Unable to identify the logged-in advisor.";

    return;
}


// ==========================================
// GET SYS_USER RECORD
// ==========================================

var advisor =
    new GlideRecord("sys_user");


if (!advisor.get(currentUserId)) {

    data.error =
        "Advisor user record could not be found.";

    return;
}


// ==========================================
// VERIFY ADVISOR ROLE
// ==========================================

var advisorRole =
    "x_snc_visaguardi_0.advisor";

var roleGR =
    new GlideRecord("sys_user_has_role");

roleGR.addQuery(
    "user",
    currentUserId
);

roleGR.addQuery(
    "role.name",
    advisorRole
);

roleGR.setLimit(1);
roleGR.query();


if (!roleGR.next()) {

    data.error =
        "The logged-in account is not an Advisor.";

    return;
}


// ==========================================
// BUILD ADVISOR PROFILE
// ==========================================

data.advisor_found = true;


data.advisor.sys_id =
    advisor.getUniqueValue();


data.advisor.user_name =
    advisor.getValue("user_name");


data.advisor.full_name =
    advisor.getDisplayValue();


data.advisor.first_name =
    advisor.getValue("first_name");


data.advisor.last_name =
    advisor.getValue("last_name");


data.advisor.email =
    advisor.getValue("email");


data.advisor.title =
    advisor.getValue("title");


data.advisor.department =
    advisor.getDisplayValue("department");


data.advisor.mobile_phone =
    advisor.getValue("mobile_phone");


data.advisor.location =
    advisor.getDisplayValue("location");


data.advisor.last_login =
    advisor.getDisplayValue("last_login");
})();


