          <i class="fa fa-exclamation-triangle"></i> 
        </div> 
        <div class="metric-data"> 
          <span class="metric-number text-red">{{c.getHighRiskCount()}}</span> 
          <span class="metric-label">HIGH RISK</span> 
          <span class="metric-subtext text-red">Compliance alert</span> 
        </div> 
      </div> 
    </div> 
  </div> 

  <!-- Main Students Table Card --> 
  <div class="vg-card margin-top-lg"> 
    <div class="vg-card-header"> 
      <div class="header-left"> 
        <h4><i class="fa fa-graduation-cap"></i> International Student Roster</h4> 
      </div> 

      <!-- Filter Pills & Search Bar --> 
      <div class="header-right"> 
        <div class="btn-group filter-pills"> 
          <button type="button" class="btn btn-sm" ng-class="{'active': c.currentFilter === 'ALL'}" ng-click="c.setFilter('ALL')">All</button> 
          <button type="button" class="btn btn-sm" ng-class="{'active': c.currentFilter === 'Active'}" ng-click="c.setFilter('Active')">Active</button> 
          <button type="button" class="btn btn-sm" ng-class="{'active': c.currentFilter === 'Pending'}" ng-click="c.setFilter('Pending')">Pending</button> 
          <button type="button" class="btn btn-sm" ng-class="{'active': c.currentFilter === 'HighRisk'}" ng-click="c.setFilter('HighRisk')">High Risk</button> 
        </div> 
        <div class="search-wrapper"> 
          <i class="fa fa-search search-icon"></i> 
          <input type="text" class="form-control input-sm search-input" placeholder="Search student, SEVIS ID, major..." ng-model="c.searchQuery"> 
        </div> 
      </div> 
    </div> 

    <!-- Table --> 
    <div class="table-responsive"> 
      <table class="table vg-table"> 
        <thead> 
          <tr> 
            <th>Student Name</th> 
            <th>SEVIS ID</th> 
            <th>Visa Type</th> 
            <th>Major / Program</th> 
            <th>Status</th> 
            <th>Risk Level</th> 
            <th class="text-right">Actions</th> 
          </tr> 
        </thead> 
        <tbody> 
          <tr ng-repeat="student in c.data.students | filter:c.filterStudents"> 
            <td> 
              <div class="student-cell"> 
                <span class="student-name">{{student.name}}</span> 
                <span class="student-email">{{student.email}}</span> 
              </div> 
            </td> 
            <td><span class="sevis-badge">{{student.sevis_id}}</span></td> 
            <td><span class="type-badge">{{student.visa_type}}</span></td> 
            <td><span class="program-text">{{student.program}}</span></td> 
            <td> 
              <span class="status-pill" ng-class="{'pill-green': student.status === 'Active', 'pill-orange': student.status === 'Pending', 'pill-red': student.status === 'Critical' || student.status === 'Terminated'}"> 
                {{student.status}} 
              </span> 
            </td> 
            <td> 
              <span class="risk-pill" ng-class="{'risk-low': student.risk === 'Low', 'risk-med': student.risk === 'Medium', 'risk-high': student.risk === 'High'}"> 
                {{student.risk}} 
              </span> 
            </td> 
            <td class="text-right"> 
              <button class="btn btn-xs btn-review" ng-click="c.viewProfile(student)"> 
                <i class="fa fa-id-card-o"></i> View Profile 
              </button> 
            </td> 
          </tr> 
          <tr ng-if="(c.data.students | filter:c.filterStudents).length === 0"> 
            <td colspan="7" class="text-center text-muted pad-lg"> 
              <em>No students found matching the search criteria.</em> 
            </td> 
          </tr> 
        </tbody> 
      </table> 
    </div> 
  </div> 
