    margin-bottom: 24px;

    box-shadow:
        0 8px 22px rgba(9,30,58,.14);

}


.vg-workload-container .hero-content h2 {

    margin: 0 0 7px;

    font-size: 24px;

    font-weight: 700;

    color: #fff;

}


.vg-workload-container .hero-content p {

    margin: 0;

    font-size: 13px;

    color: rgba(255,255,255,.82);

}


/* =====================================================
   METRIC CARDS
   ===================================================== */

.vg-workload-container .metric-row {

    margin-left: -8px;

    margin-right: -8px;

    margin-bottom: 10px;

}


.vg-workload-container .metric-row > div {

    padding-left: 8px;

    padding-right: 8px;

    margin-bottom: 16px;

}


.vg-workload-container .vg-metric-card {

    background: #fff;

    border: 1px solid #e8edf4;

    border-radius: 13px;

    padding: 19px;

    min-height: 96px;

    display: flex;

    align-items: center;

    gap: 15px;

    box-shadow:
        0 4px 15px rgba(20,40,80,.04);

}


.vg-workload-container .metric-icon {

    width: 50px;

    height: 50px;

    min-width: 50px;

    border-radius: 50%;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 19px;

}


.vg-workload-container .blue-circle {

    background: #e8f0fe;

    color: #0066ff;

}


.vg-workload-container .green-circle {

    background: #e6f4ea;

    color: #00a86b;

}


.vg-workload-container .orange-circle {

    background: #fff3dc;

    color: #f39a22;

}


.vg-workload-container .red-circle {

    background: #fde8e8;

    color: #e55353;

}


.vg-workload-container .metric-data {

    display: flex;

    flex-direction: column;

}


.vg-workload-container .metric-number {

    font-size: 24px;

    font-weight: 750;

