}


.vg-workload-container .metric-subtext {

    font-size: 11px;

    font-weight: 600;

}


.text-blue {
    color: #0066ff;
}

.text-green {
    color: #00a86b;
}

.text-orange {
    color: #f39a22;
}

.text-red {
    color: #e55353;
}


/* =====================================================
   CARD
   ===================================================== */

.vg-workload-container .vg-card {

    background: #fff;

    border: 1px solid #e8edf4;

    border-radius: 14px;

    padding: 22px 24px;

    margin-bottom: 20px;

    box-shadow:
        0 4px 16px rgba(20,40,80,.04);

}


.vg-workload-container .vg-card-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding-bottom: 16px;

