    }


    .search-input {

        width: 100%;

    }


    .workload-name {

        width: 105px;

        min-width: 105px;

    }

}

sp_widget.script:
(function() {

    /* =========================================================
       VISA GUARDIAN AI
       DSO ADVISOR WORKLOAD
       ========================================================= */

    data.advisors = [];
    data.totalAdvisors = 0;
    data.activeCases = 0;
    data.overloadedCount = 0;
    data.overdueCases = 0;
    data.pendingActionsCount = 0;
    data.avgCapacity = 0;
    data.aiInsight = "";

    /* =========================================================
       EXACT TABLE NAMES
       ========================================================= */

    var ADVISOR_TABLE =
        "x_snc_visaguardi_0_advisor_profiles";

    var VISA_CASE_TABLE =
        "x_snc_visaguardi_0_visa_case";


    /* =========================================================
       HELPER
       ========================================================= */

    function findField(gr, fields) {

        for (var i = 0; i < fields.length; i++) {

            if (gr.isValidField(fields[i])) {
                return fields[i];
            }

        }

        return "";
    }


    /* =========================================================
       GET DISPLAY OR VALUE
       ========================================================= */

    function getFieldText(gr, fieldName) {

        if (!fieldName || !gr.isValidField(fieldName)) {
            return "";
        }

        var displayValue =
            gr.getDisplayValue(fieldName);

        var value =
            gr.getValue(fieldName);

        return String(
            displayValue || value || ""
        ).trim();
    }


    /* =========================================================
       NORMALIZE TEXT
       ========================================================= */

    function normalize(value) {

        if (!value) {
            return "";
        }

        return String(value)
            .trim()
            .toLowerCase();

    }


    /* =========================================================
       FIND ADVISOR PROFILE TABLE
       ========================================================= */

    var advisorGR =
        new GlideRecord(ADVISOR_TABLE);


    if (!advisorGR.isValid()) {

        data.aiInsight =
            "Unable to access Advisor Profiles table: " +
            ADVISOR_TABLE;

        return;
    }


    /* =========================================================
       DETECT ADVISOR FIELDS
       ========================================================= */

    var nameField =
        findField(
            advisorGR,
            [
                "full_name",
                "name",
                "advisor_name"
            ]
        );


    var firstNameField =
        findField(
            advisorGR,
            [
                "first_name",
                "firstname"
            ]
        );


    var lastNameField =
        findField(
            advisorGR,
            [
                "last_name",
                "lastname"
            ]
        );


    var emailField =
        findField(
            advisorGR,
            [
                "email",
                "email_address",
                "advisor_email"
            ]
        );


    var departmentField =
        findField(
            advisorGR,
            [
                "department",
                "advisor_department"
            ]
        );


    var jobTitleField =
        findField(
            advisorGR,
            [
                "job_title",
                "title",
                "role"
            ]
        );


    var activeField =
        findField(
            advisorGR,
            [
                "active",
                "is_active"
            ]
        );


    var maxCapacityField =
        findField(
            advisorGR,
            [
                "max_capacity",
                "capacity",
                "case_capacity"
            ]
        );


    /* =========================================================
       LOAD ACTIVE ADVISORS
       ========================================================= */

    if (activeField) {

        advisorGR.addQuery(
            activeField,
            true
        );

    }

    advisorGR.query();


    /* =========================================================
       ADVISOR LOOKUP MAPS
       ========================================================= */

    var advisorMap = {};

    var advisorNameMap = {};

    var advisorEmailMap = {};

    var totalCapacityPercent = 0;


    /* =========================================================
       READ ADVISOR PROFILES
       ========================================================= */

    while (advisorGR.next()) {

        var advisorSysId =
            advisorGR.getUniqueValue();


        /* -----------------------------------------------------
           NAME
           ----------------------------------------------------- */

        var fullName = "";


        if (nameField) {

            fullName =
                advisorGR.getDisplayValue(
                    nameField
                ) || "";

        }


        if (!fullName && firstNameField) {

            fullName =
                advisorGR.getValue(
                    firstNameField
                ) || "";


            if (lastNameField) {

                fullName +=
                    " " +
                    (
                        advisorGR.getValue(
                            lastNameField
                        ) || ""
                    );

            }

        }


        fullName =
            String(fullName).trim();


        if (!fullName) {
            fullName = "Advisor";
        }


        /* -----------------------------------------------------
           EMAIL
           ----------------------------------------------------- */

        var email = "";

        if (emailField) {

            email =
                advisorGR.getValue(
                    emailField
                ) || "";

        }


        /* -----------------------------------------------------
           DEPARTMENT
           ----------------------------------------------------- */

        var department = "";

        if (departmentField) {

            department =
                advisorGR.getDisplayValue(
                    departmentField
                ) ||
                advisorGR.getValue(
                    departmentField
                ) ||
                "";

        }


        /* -----------------------------------------------------
           ROLE
           ----------------------------------------------------- */

        var role = "Advisor";

        if (jobTitleField) {

            role =
                advisorGR.getDisplayValue(
                    jobTitleField
                ) ||
                advisorGR.getValue(
                    jobTitleField
                ) ||
                "Advisor";

        }


        /* -----------------------------------------------------
           CAPACITY
           ----------------------------------------------------- */

        var maxCapacity = 25;

        if (maxCapacityField) {

            var configuredCapacity =
                parseInt(
                    advisorGR.getValue(
                        maxCapacityField
                    ),
                    10
                );


            if (
                !isNaN(configuredCapacity) &&
                configuredCapacity > 0
            ) {

                maxCapacity =
                    configuredCapacity;

            }

        }


        /* -----------------------------------------------------
           INITIALS
           ----------------------------------------------------- */

        var nameParts =
            fullName.split(/\s+/);

        var initials = "";

        if (nameParts.length >= 2) {

            initials =
                nameParts[0].charAt(0) +
                nameParts[
                    nameParts.length - 1
                ].charAt(0);

        } else {

            initials =
                fullName.substring(
                    0,
                    2
                );

        }

        initials =
            initials.toUpperCase();


        /* -----------------------------------------------------
           ADVISOR OBJECT
           ----------------------------------------------------- */

        var advisor = {

            sys_id: advisorSysId,

            name: fullName,

            email: email,

            department: department,

            role: role,

            initials: initials,

            active_cases: 0,

            max_capacity: maxCapacity,

            capacity_percent: 0,

            high_risk: 0,

            sla_at_risk: 0,

            status: "Available"

        };


        data.advisors.push(
            advisor
        );


        /* -----------------------------------------------------
           MULTIPLE LOOKUP METHODS
           ----------------------------------------------------- */

        advisorMap[
            advisorSysId
        ] = advisor;


        advisorNameMap[
            normalize(fullName)
        ] = advisor;


        if (email) {

            advisorEmailMap[
                normalize(email)
            ] = advisor;

        }


        data.totalAdvisors++;

    }


    /* =========================================================
       VISA CASE TABLE
       ========================================================= */

    var caseGR =
        new GlideRecord(
            VISA_CASE_TABLE
        );


    if (!caseGR.isValid()) {

        data.aiInsight =
            "Unable to access Visa Case table: " +
            VISA_CASE_TABLE;

        return;
    }


    /* =========================================================
       FIND ADVISOR ASSIGNMENT FIELD
       ========================================================= */

    var advisorAssignmentField = "";


    var possibleAdvisorFields = [

        "advisor",
        "assigned_advisor",
        "advisor_profile",
        "assigned_to",
        "assignedadvisor",
        "assigned_to_advisor"

    ];


    for (
        var af = 0;
        af < possibleAdvisorFields.length;
        af++
    ) {

        if (
            caseGR.isValidField(
                possibleAdvisorFields[af]
            )
        ) {

            advisorAssignmentField =
                possibleAdvisorFields[af];

            break;

        }

    }


    /* =========================================================
       IF NOT FOUND - SEARCH DICTIONARY
       ========================================================= */

    if (!advisorAssignmentField) {

        var dictionaryGR =
            new GlideRecord(
                "sys_dictionary"
            );


        dictionaryGR.addQuery(
            "name",
            VISA_CASE_TABLE
        );


        dictionaryGR.query();


        while (
            dictionaryGR.next()
        ) {

            var element =
                dictionaryGR.getValue(
                    "element"
                );


            if (!element) {
                continue;
            }


            var elementLower =
                element.toLowerCase();


            if (
                elementLower.indexOf(
                    "advisor"
                ) !== -1
            ) {

                if (
                    caseGR.isValidField(
                        element
                    )
                ) {

                    advisorAssignmentField =
                        element;

                    break;

                }

            }

        }

    }


    /* =========================================================
       PROCESS VISA CASES
       ========================================================= */

    caseGR.query();


    while (caseGR.next()) {

        /* -----------------------------------------------------
           CASE STATUS
           ----------------------------------------------------- */

        var caseStage = "";


        if (
            caseGR.isValidField(
                "case_stage"
            )
        ) {

            caseStage =
                caseGR.getDisplayValue(
                    "case_stage"
                ) ||
                caseGR.getValue(
                    "case_stage"
                ) ||
                "";

        }


        if (
            !caseStage &&
            caseGR.isValidField(
                "status"
            )
        ) {

            caseStage =
                caseGR.getDisplayValue(
                    "status"
                ) ||
                caseGR.getValue(
                    "status"
                ) ||
                "";

        }


        var stage =
            normalize(caseStage);


        /* -----------------------------------------------------
           IGNORE CLOSED / COMPLETED CASES
           ----------------------------------------------------- */

        if (

            stage.indexOf("approved") !== -1 ||

            stage.indexOf("resolved") !== -1 ||

            stage.indexOf("closed") !== -1 ||

            stage.indexOf("completed") !== -1

        ) {

            continue;

        }


        data.activeCases++;


        /* =====================================================
           ASSIGNED ADVISOR
           ===================================================== */

        if (!advisorAssignmentField) {
            continue;
        }


        var assignedValue =
            caseGR.getValue(
                advisorAssignmentField
            );


        var assignedDisplay =
            caseGR.getDisplayValue(
                advisorAssignmentField
            );


        var assignedAdvisor =
            null;


        /* -----------------------------------------------------
           METHOD 1 - SYS ID
           ----------------------------------------------------- */

        if (
            assignedValue &&
            advisorMap[assignedValue]
        ) {

            assignedAdvisor =
                advisorMap[
                    assignedValue
                ];

        }


        /* -----------------------------------------------------
           METHOD 2 - DISPLAY NAME
           ----------------------------------------------------- */

        if (
            !assignedAdvisor &&
            assignedDisplay
        ) {

            assignedAdvisor =
                advisorNameMap[
                    normalize(
                        assignedDisplay
                    )
                ];

        }


        /* -----------------------------------------------------
           METHOD 3 - EMAIL
           ----------------------------------------------------- */

        if (
            !assignedAdvisor &&
            assignedDisplay
        ) {

            assignedAdvisor =
                advisorEmailMap[
                    normalize(
                        assignedDisplay
                    )
                ];

        }


        /* -----------------------------------------------------
           METHOD 4 - VALUE AS NAME
           ----------------------------------------------------- */

        if (
            !assignedAdvisor &&
            assignedValue
        ) {

            assignedAdvisor =
                advisorNameMap[
                    normalize(
                        assignedValue
                    )
                ];

        }


        /* -----------------------------------------------------
           NO MATCH
           ----------------------------------------------------- */

        if (!assignedAdvisor) {
            continue;
        }


        /* =====================================================
           INCREMENT ACTIVE CASE
           ===================================================== */

        assignedAdvisor.active_cases++;


        /* =====================================================
           PRIORITY / RISK
           ===================================================== */

        var priority = "";


        if (
            caseGR.isValidField(
                "priority"
            )
        ) {

            priority =
                caseGR.getDisplayValue(
                    "priority"
                ) ||
                caseGR.getValue(
                    "priority"
                ) ||
                "";

        }


        var priorityLower =
            normalize(priority);


        if (

            priorityLower.indexOf(
                "high"
            ) !== -1 ||

            priorityLower.indexOf(
                "critical"
            ) !== -1

        ) {

            assignedAdvisor.high_risk++;

        }


        /* =====================================================
           SLA
           ===================================================== */

        if (
            caseGR.isValidField(
                "sys_created_on"
            )
        ) {

            var created =
                new GlideDateTime(
                    caseGR.getValue(
                        "sys_created_on"
                    )
                );


            var now =
                new GlideDateTime();


            var elapsed =
                now.getNumericValue() -
                created.getNumericValue();


            var hours =
                elapsed / 3600000;


            if (hours >= 24) {

                assignedAdvisor.sla_at_risk++;

            }


            if (hours >= 48) {

                data.overdueCases++;

            }

        }


        /* =====================================================
           PENDING ACTION
           ===================================================== */

        var pendingStage =
            normalize(caseStage);


        if (

            pendingStage.indexOf(
                "pending"
            ) !== -1 ||

            pendingStage.indexOf(
                "review"
            ) !== -1 ||

            pendingStage.indexOf(
                "in progress"
            ) !== -1

        ) {

            data.pendingActionsCount++;

        }

    }


    /* =========================================================
       CALCULATE ADVISOR CAPACITY
       ========================================================= */

    for (
        var i = 0;
        i < data.advisors.length;
        i++
    ) {

        var current =
            data.advisors[i];


        current.capacity_percent =
            Math.round(
                (
                    current.active_cases /
                    current.max_capacity
                ) * 100
            );


        if (
            current.capacity_percent > 100
        ) {

            current.capacity_percent = 100;

        }


        totalCapacityPercent +=
            current.capacity_percent;


        /* -----------------------------------------------------
           STATUS
           ----------------------------------------------------- */

        if (
            current.capacity_percent >= 100
        ) {

            current.status =
                "At Capacity";


            data.overloadedCount++;


        } else if (
            current.capacity_percent >= 85
        ) {

            current.status =
                "Busy";


            data.overloadedCount++;


        } else {

            current.status =
                "Available";

        }

    }


    /* =========================================================
       AVERAGE CAPACITY
       ========================================================= */

    if (
        data.totalAdvisors > 0
    ) {

        data.avgCapacity =
            Math.round(
                totalCapacityPercent /
                data.totalAdvisors
            );

    }


    /* =========================================================
       AI WORKLOAD INSIGHT
       ========================================================= */

    if (
        data.totalAdvisors === 0
    ) {

        data.aiInsight =
            "No active advisor profiles were found.";

    }

    else if (
        data.overloadedCount > 0 &&
        data.overdueCases > 0
    ) {

        data.aiInsight =
            data.overloadedCount +
            " advisor(s) are above the recommended capacity threshold and " +
            data.overdueCases +
            " case(s) are overdue. Review workload distribution and prioritize overdue cases.";

    }

    else if (
        data.overloadedCount > 0
    ) {

        data.aiInsight =
            data.overloadedCount +
            " advisor(s) are above the recommended 85% workload threshold. Consider redistributing active cases.";

    }

    else if (
        data.overdueCases > 0
    ) {

        data.aiInsight =
            data.overdueCases +
            " case(s) have exceeded the SLA threshold. Advisor follow-up is recommended.";

    }

    else {

        data.aiInsight =
            "Advisor workload is currently within the configured capacity threshold. Continue monitoring case distribution and SLA performance.";

    }


    /* =========================================================
       DIAGNOSTIC INFORMATION
       ========================================================= */

    if (!advisorAssignmentField) {

        data.aiInsight +=
            " IMPORTANT: No advisor assignment field was found on " +
            VISA_CASE_TABLE +
            ". Add/use a reference field such as assigned_advisor.";

    }

})();
